#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    // Validate shift argument: optional leading '+' or '-', then digits only
    const char *shift_str = argv[1];
    const char *p = shift_str;
    if (*p == '+' || *p == '-') {
        p++;
    }
    if (*p == '\0') {
        puts("USAGE");
        return 0;
    }
    for (; *p; ++p) {
        if (!isdigit((unsigned char)*p)) {
            puts("USAGE");
            return 0;
        }
    }
    long shift = strtol(shift_str, NULL, 10);
    int norm = (int)(shift % 26);
    if (norm < 0) norm += 26;

    const char *text = argv[2];
    size_t len = strlen(text);
    if (len > 1024) { // 0x400
        puts("USAGE");
        return 0;
    }
    for (size_t i = 0; i < len; ++i) {
        char c = text[i];
        if (c >= 'A' && c <= 'Z') {
            putchar(((c - 'A' + norm) % 26) + 'A');
        } else if (c >= 'a' && c <= 'z') {
            putchar(((c - 'a' + norm) % 26) + 'a');
        } else {
            putchar(c);
        }
    }
    putchar('\n');
    return 0;
}
